import{_ as e,c as r,o as h,af as i}from"./chunks/framework.BKeRpnBD.js";const p=JSON.parse('{"title":"師","description":"周易正義 - 師","frontmatter":{"title":"師","description":"周易正義 - 師"},"headers":[],"relativePath":"classics/zhengyi/007.md","filePath":"classics/zhengyi/007.md"}'),l={name:"classics/zhengyi/007.md"};function n(d,a,t,o,s,c){return h(),r("div",null,[...a[0]||(a[0]=[i('<blockquote><p>地水師</p></blockquote><blockquote><p>卦辭：貞，丈人吉，無咎。</p></blockquote><blockquote><p>彖曰：師，眾也；貞，正也。能以眾正，可以王矣。剛中而應，行險而順，以此毒天下，而民從之，吉又何咎矣。</p></blockquote><h1 id="師" tabindex="-1">師 <a class="header-anchor" href="#師" aria-label="Permalink to “師”">​</a></h1><p>王弼：丈人，嚴莊之稱也。為師之正，丈人乃吉也。興役動眾無功，罪也，故吉乃無咎也。</p><h3 id="疏" tabindex="-1">疏 <a class="header-anchor" href="#疏" aria-label="Permalink to “疏”">​</a></h3><p>“師：貞，丈人吉，無咎”。○正義曰：“師”，眾也。貞，正也。丈人謂嚴莊尊重之人，言為師之正，唯得嚴莊丈人監臨主領，乃得“吉無咎”。若不得丈人監臨之，無不畏懼，不能齊眾，必有咎害。○注“丈人嚴戒之稱也”至“乃無咎也”。○正義曰：“興役動眾無功，罪”者，監臨師旅，當以威嚴，則有功勞，乃得無咎；若其不以威嚴，師必無功而獲其罪，故云“興役動眾無功，罪”也。</p><h2 id="《彖》曰-​" tabindex="-1">《彖》曰： ​ <a class="header-anchor" href="#《彖》曰-​" aria-label="Permalink to “《彖》曰： ​”">​</a></h2><h3 id="師-眾也。貞-正也。能以眾正-可以王矣。剛中而應-行險而順-以此毒天下而民從之-吉又何咎矣-​" tabindex="-1">師，眾也。貞，正也。能以眾正，可以王矣。剛中而應，行險而順，以此毒天下而民從之，吉又何咎矣？ ​ <a class="header-anchor" href="#師-眾也。貞-正也。能以眾正-可以王矣。剛中而應-行險而順-以此毒天下而民從之-吉又何咎矣-​" aria-label="Permalink to “師，眾也。貞，正也。能以眾正，可以王矣。剛中而應，行險而順，以此毒天下而民從之，吉又何咎矣？ ​”">​</a></h3><p>王弼：毒猶役也。</p><h3 id="疏-1" tabindex="-1">疏 <a class="header-anchor" href="#疏-1" aria-label="Permalink to “疏”">​</a></h3><p>“彖曰”至“又何咎矣”。○正義曰：“師，眾也。貞，正也。能以眾正，可以王矣”者，此釋師卦之名，並明用師有功之義。但師訓既多，或訓為法，或訓為長，恐此師名取法之與長，故特明之師訓為眾也。貞為正也。貞之為正，其義已見於此，復雲““貞，正”者，欲見齊眾必須以正，故訓貞為正也。與下文為首引之勢，故云“能以眾正，可以王矣”。“剛中而應”者，“剛中”謂九二，而“應”謂六五。“行險而順”者，“行險”謂下體坎也，而“順”謂上體坤也。若剛中而無應，或有應而不剛中，或行險而不柔順，皆不可行師得吉也。“以此毒天下而民從之，吉又何咎矣”者，毒猶役也，若用此諸德使役天下之眾，人必從之以得其吉，又何無功而咎責乎？自“剛中”以下釋“丈人吉，無咎”也，言丈人能備此諸德也。</p><h3 id="《象》曰-地中有水-師。君子以容民畜眾。-​" tabindex="-1">《象》曰：地中有水，師。君子以容民畜眾。 ​ <a class="header-anchor" href="#《象》曰-地中有水-師。君子以容民畜眾。-​" aria-label="Permalink to “《象》曰：地中有水，師。君子以容民畜眾。 ​”">​</a></h3><h3 id="疏-2" tabindex="-1">疏 <a class="header-anchor" href="#疏-2" aria-label="Permalink to “疏”">​</a></h3><p>正義曰：“君子以容民畜眾”者，言君子法此師卦，容納其民，畜養其眾。若為人除害，使眾得寧，此則“容民畜眾”也。又為師之，主雖尚威嚴，當赦其小過，不可純用威猛於軍師之中，亦是容民畜眾之義。所以《象》稱“地中有水”，欲見地能包水，水又眾大，是容民畜眾之象。若其不然，或當雲“地在水上”，或雲“上地下水”，或雲“水上有地”。今雲“地中有水”，蓋取容、畜之義也。</p><h2 id="初六-師出以律-否臧兇。-​" tabindex="-1">初六：師出以律，否臧兇。 ​ <a class="header-anchor" href="#初六-師出以律-否臧兇。-​" aria-label="Permalink to “初六：師出以律，否臧兇。 ​”">​</a></h2><p>王弼：為師之始，齊師者也。齊眾以律，失律則散。故師出以律，律不可失。失律而臧，何異於否？失令有功，法所不赦。故師出不以律，否臧皆兇。</p><h3 id="疏-3" tabindex="-1">疏 <a class="header-anchor" href="#疏-3" aria-label="Permalink to “疏”">​</a></h3><p>“初六師出”至“否臧兇”。○正義曰：“初六師出以律”者，律，法也。初六為師之始，是整齊師眾者也。既齊整師眾，使師出之時，當須以其法制整齊之，故云“師出以律”也。“否臧兇”者，若其失律行師，無問否之與臧，皆為兇也。“否”謂破敗，“臧”謂有功。然“否”為破敗，即是兇也。何須更雲“否臧兇”者，本意所明，雖臧亦兇。“臧”文既單，故以“否”配之，欲盛言臧兇，不可單言，故云否之與臧，皆為兇也。○注“為師之始”至“否臧皆兇”。○正義曰：“為師之始，齊師者也”者，以師之初爻，故云“為師之始”。在師之首，先唱發始，是齊整師眾者也。“失律而臧，何異於否”者，若棄失法律，不奉法而行，雖有功而臧，何異於否也？“失令有功，法所不赦”者，解“何異於否”之義。令則法律也。若失此法令，雖有功勞，軍法所不容赦，故云“何異於否”。然閫外之事，將軍所載，臨事制宜，不必皆依君命，何得有功“法所不赦”者：凡為師之體，理非一端，量事制宜，隨時進退，此則將軍所制，隨時施行。若苟順私情，故違君命，犯律觸法，則事不可赦耳。</p><h3 id="《象》曰-師出以律-失律兇也。-​" tabindex="-1">《象》曰：“師出以律”，失律兇也。 ​ <a class="header-anchor" href="#《象》曰-師出以律-失律兇也。-​" aria-label="Permalink to “《象》曰：“師出以律”，失律兇也。 ​”">​</a></h3><h3 id="疏-4" tabindex="-1">疏 <a class="header-anchor" href="#疏-4" aria-label="Permalink to “疏”">​</a></h3><p>正義曰“失律兇”者，釋“師出以律”之義。言所以必須以律者，以其失律則兇。反經之文，以明經義。</p><h2 id="九二-在師中-吉-無咎-王三錫命。-​" tabindex="-1">九二：在師中，吉，無咎，王三錫命。 ​ <a class="header-anchor" href="#九二-在師中-吉-無咎-王三錫命。-​" aria-label="Permalink to “九二：在師中，吉，無咎，王三錫命。 ​”">​</a></h2><p>王弼：以剛居中，而應於上，在師而得其中者也。承上之寵，為師之主，任大役重，無功則兇，故吉乃無咎也。行師得吉，莫善懷邦，邦懷眾服，錫莫重焉，故乃得成命。</p><h3 id="疏-5" tabindex="-1">疏 <a class="header-anchor" href="#疏-5" aria-label="Permalink to “疏”">​</a></h3><p>“九二”至“王三錫命”。○正義曰：“在師中吉”者，以剛居中而應於五，是“在師中吉”也。“無咎”者，承上之寵，為師之主，任大役重，無功則兇，故吉乃無咎。“王三錫命”者，以其有功，故王三加錫命。○注“以剛居中”至“故乃得成命”。○正義曰：“在師而得中”者，觀注之意，以“在師中”為句，其“吉”字屬下；觀《象》之文，“在師中吉，承天寵”者，則似“吉”字屬上。此“吉”之一字上下兼該，故註文屬下，《象》文屬上，但《象》略其“無咎”之字，故“吉”屬“師中”也。“故乃得成命”者，案《曲禮》雲：“三賜不及車馬。”一命受爵，再命受服，三命受車馬。三賜三命，而尊之得成，故“乃得成命”也。</p><h3 id="《象》曰-在師中吉-承天寵也。-王三錫命-懷萬邦也。-​" tabindex="-1">《象》曰：“在師中吉”，承天寵也。“王三錫命”，懷萬邦也。 ​ <a class="header-anchor" href="#《象》曰-在師中吉-承天寵也。-王三錫命-懷萬邦也。-​" aria-label="Permalink to “《象》曰：“在師中吉”，承天寵也。“王三錫命”，懷萬邦也。 ​”">​</a></h3><h3 id="疏-6" tabindex="-1">疏 <a class="header-anchor" href="#疏-6" aria-label="Permalink to “疏”">​</a></h3><p>正義曰：“承天寵”者，釋“在師中吉”之義也。正謂承受五之恩寵，故“中吉”也。“懷萬邦也”者，以其有功，能招懷萬邦，故被“王三錫命”也。</p><h2 id="六三-師或輿尸-兇。-​" tabindex="-1">六三：師或輿尸，兇。 ​ <a class="header-anchor" href="#六三-師或輿尸-兇。-​" aria-label="Permalink to “六三：師或輿尸，兇。 ​”">​</a></h2><p>王弼：以陰處陽，以柔乘剛，進則無應，退無所守，以此用師，宜獲“輿尸”之兇。</p><h3 id="疏-7" tabindex="-1">疏 <a class="header-anchor" href="#疏-7" aria-label="Permalink to “疏”">​</a></h3><p>“六三師或輿尸兇”。○正義曰：以陰處陽，以柔乘剛，進無所應，退無所守，以此用師，或有輿尸之兇。○注“以陰處陽”至“輿尸之兇”。○正義曰：“退無所守”者，倒退而下，乘二之剛，已又以陰居陽，是“退無所守”。</p><h3 id="《象》曰-師或輿尸-大無功也。-​" tabindex="-1">《象》曰：“師或輿尸”，大無功也。 ​ <a class="header-anchor" href="#《象》曰-師或輿尸-大無功也。-​" aria-label="Permalink to “《象》曰：“師或輿尸”，大無功也。 ​”">​</a></h3><h3 id="疏-8" tabindex="-1">疏 <a class="header-anchor" href="#疏-8" aria-label="Permalink to “疏”">​</a></h3><p>正義曰：“大無功也”者，釋“輿尸”之義，以其輿尸，則大無功也。</p><h2 id="六四-師左次-無咎。-​" tabindex="-1">六四：師左次，無咎。 ​ <a class="header-anchor" href="#六四-師左次-無咎。-​" aria-label="Permalink to “六四：師左次，無咎。 ​”">​</a></h2><p>王弼：得位而無應，無應不可以行，得位則可以處，故左次之，而無咎也。行師之法，欲右背高，故左次之。</p><h3 id="疏-9" tabindex="-1">疏 <a class="header-anchor" href="#疏-9" aria-label="Permalink to “疏”">​</a></h3><p>“六四，師左次，無咎”。○正義曰：六四得位而無應，無應不可以行，得位則可以處，故云“師左次，無咎”。故師在高險之左，以次止則無兇咎也。○注“行師之法”至“故左次之”。○正義曰：“行師之法，欲右背高”者，此兵法也。故《漢書》韓信雲：“兵法欲右背山陵，前左水澤。”</p><h3 id="《象》曰-左次無咎-未失常也。雖不能有獲-足以不失其常也。-​" tabindex="-1">《象》曰：“左次無咎”，未失常也。雖不能有獲，足以不失其常也。 ​ <a class="header-anchor" href="#《象》曰-左次無咎-未失常也。雖不能有獲-足以不失其常也。-​" aria-label="Permalink to “《象》曰：“左次無咎”，未失常也。雖不能有獲，足以不失其常也。 ​”">​</a></h3><h3 id="疏-10" tabindex="-1">疏 <a class="header-anchor" href="#疏-10" aria-label="Permalink to “疏”">​</a></h3><p>正義曰：“未失常”者，釋“無咎”之義，以其雖未有功，未失常道。</p><h2 id="六五-田有禽-利執言-無咎。長子帥師-弟子輿尸-貞兇。-​" tabindex="-1">六五：田有禽，利執言，無咎。長子帥師，弟子輿尸，貞兇。 ​ <a class="header-anchor" href="#六五-田有禽-利執言-無咎。長子帥師-弟子輿尸-貞兇。-​" aria-label="Permalink to “六五：田有禽，利執言，無咎。長子帥師，弟子輿尸，貞兇。 ​”">​</a></h2><p>王弼：處師之時，柔得尊位，陰不先唱，柔不犯物，犯而後應，往必得直，故“田有禽”也。物先犯己，故可以執言而無咎也。柔非軍帥，陰非剛武，故不躬行，必以授也。授不得王，則眾不從，故“長子帥師”可也。弟子之兇，故其宜也。</p><h3 id="疏-11" tabindex="-1">疏 <a class="header-anchor" href="#疏-11" aria-label="Permalink to “疏”">​</a></h3><p>“六五田有禽”至“輿尸貞兇”。○正義曰：“田有禽，利執言”者，柔得尊位，陰不先唱，柔不犯物，犯而後應，往必得直，故往即有功。猶如田中有禽而來犯苗，若往獵之，則無咎過也。人之修田，非禽之所犯。王者守國，非叛者所亂。禽之犯苗，則可獵取。叛人亂國，則可誅之。此假他象以喻人事，故“利執言，無咎”，已不直則有咎。己今得直，故可以執此言往問之而無咎也。“長子帥師，弟子輿尸，貞兇”者，以已是柔，不可為軍帥。已又是陰，身非剛武，不可以親行，故須役任長子、弟子之等。若任役長子，則可以帥師。若任用弟子，則軍必破敗而輿尸，是為正之兇。莊氏雲：“‘長子’謂九二，德長於人。‘弟子’謂六三，德劣於物。”今案：《象》辭雲“長子帥師，以中行也”，是九二居中也。“弟子輿尸，使不當也”，謂六三失位也。○注至“往必得直”。○正義曰：“往必得直”者，見犯乃得欲往徵之，則於理正直，故云“往必得直”。</p><h3 id="《象》曰-長子帥師-以中行也。-弟子輿尸-使不當也。-​" tabindex="-1">《象》曰：“長子帥師”，以中行也。“弟子輿尸”，使不當也。 ​ <a class="header-anchor" href="#《象》曰-長子帥師-以中行也。-弟子輿尸-使不當也。-​" aria-label="Permalink to “《象》曰：“長子帥師”，以中行也。“弟子輿尸”，使不當也。 ​”">​</a></h3><h2 id="上六-大君有命-開國承家-小人勿用。-​" tabindex="-1">上六：大君有命，開國承家，小人勿用。 ​ <a class="header-anchor" href="#上六-大君有命-開國承家-小人勿用。-​" aria-label="Permalink to “上六：大君有命，開國承家，小人勿用。 ​”">​</a></h2><p>王弼：處師之極，師之終也。大君之命，不失功也。開國承家，以寧邦也。小人勿用，非其道也。</p><h3 id="疏-12" tabindex="-1">疏 <a class="header-anchor" href="#疏-12" aria-label="Permalink to “疏”">​</a></h3><p>“上六大君有命”至“小人勿用”。○正義曰：“大君有命”者，上六處師之極，是師之終竟也。“大君”謂天子也，言天子爵命此上六，若其功大，使之開國為諸侯；若其功小，使之承家為卿大夫。“小人勿用”者，言開國承家，須用君子，勿用小人也。</p><h3 id="《象》曰-大君有命-以正功也。-小人勿用-必亂邦也。-​" tabindex="-1">《象》曰：“大君有命”，以正功也。“小人勿用”，必亂邦也。 ​ <a class="header-anchor" href="#《象》曰-大君有命-以正功也。-小人勿用-必亂邦也。-​" aria-label="Permalink to “《象》曰：“大君有命”，以正功也。“小人勿用”，必亂邦也。 ​”">​</a></h3><h3 id="疏-13" tabindex="-1">疏 <a class="header-anchor" href="#疏-13" aria-label="Permalink to “疏”">​</a></h3><p>正義曰：“大君有命，以正功也”者，正此上六之功也。“小人勿用，必亂邦也”者，若用小人，必亂邦國，故不得用小人也。</p>',55)])])}const f=e(l,[["render",n]]);export{p as __pageData,f as default};
